(() => {
  'use strict';
  document.documentElement.dataset.prototypePage = 'loudness';
  const presets = { reference:['REFERENCE',0,0], home:['HOME',6,2.5], punch:['PUNCH',8,2.5], night:['NIGHT',4,1.5], outdoor:['OUTDOOR',3,2.5], maxspl:['MAX SPL',0,0] };
  let active = 'home'; const $ = selector => document.querySelector(selector);
  function draw() { const canvas = $('#loudnessCanvas'), ctx = canvas.getContext('2d'), { width:w, height:h } = canvas, preset = presets[active]; ctx.clearRect(0,0,w,h); ctx.strokeStyle='rgba(235,244,246,.13)'; for(let y=28;y<h-24;y+=44){ctx.beginPath();ctx.moveTo(45,y);ctx.lineTo(w-16,y);ctx.stroke();} for(let i=0;i<10;i++){const x=45+i*(w-61)/9;ctx.beginPath();ctx.moveTo(x,18);ctx.lineTo(x,h-24);ctx.stroke();} ctx.strokeStyle='#59d5e3';ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<=w-61;i++){const t=i/(w-61), gain=preset[1]/(1+Math.pow(t*9,4))+preset[2]/(1+Math.pow((1-t)*9,4)), y=h-24-gain/10*(h-44);i?ctx.lineTo(45+i,y):ctx.moveTo(45+i,y);}ctx.stroke(); }
  function setPreset(key) { active=key; const preset=presets[key]; window.EStackPrototypeDSP.apply(config=>{config.loudnessPreset=key;config.filters.ESTACK_LOUDNESS={type:'Loudness',parameters:{fader:'Aux1',low_boost:preset[1],high_boost:preset[2]}};},'loudness preset'); render(); }
  function render() { const preset=presets[active]; $('#presetTitle').textContent=preset[0]; $('#presetSub').textContent=preset[1]?`Aux1-linked · ${preset[1].toFixed(1)} dB low / ${preset[2].toFixed(1)} dB high`:'Flat response'; $('#bassBoost').textContent=`+${preset[1].toFixed(1)} dB`; $('#highBoost').textContent=`+${preset[2].toFixed(1)} dB`; $('#loudnessPresets').innerHTML=Object.entries(presets).map(([key,item])=>`<button class="preset ${key===active?'active':''}" data-preset="${key}"><strong>${item[0]}</strong><span>LOW +${item[1].toFixed(1)} · HIGH +${item[2].toFixed(1)} dB</span></button>`).join(''); document.querySelectorAll('[data-preset]').forEach(button=>button.addEventListener('click',()=>setPreset(button.dataset.preset))); draw(); }
  $('#applyCurve').addEventListener('click',()=>window.EStackPrototypeDSP.apply(config=>{config.loudnessCurve={start:Number($('#curveStart').value),full:Number($('#curveFull').value),shape:Number($('#curveShape').value)};},'loudness curve'));
  window.EStackPrototypeDSP.subscribe((config,reason)=>{if((reason==='initial'||reason==='initial shell state')&&presets[config.loudnessPreset])active=config.loudnessPreset;$('#loudnessState').textContent=config.connected?'CAMILLADSP READY':'LOCAL SIMULATION';render();});
})();
